'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const icon=n=>`<svg aria-hidden="true"><use href="#i-${n}"/></svg>`;
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORE='kodra-fel-v2', COLORS=['#d5eaa9','#e1d6f3','#f5d4bd','#bde5ed','#f2e4a4'];
const defaultBuilder=t=>({name:t.name,color:0,rule:t.default,tests:[]});
const freshProfile=id=>({completed:[],robotLevel:0,robotSolved:[],testReports:[],elapsed:0,reflection:'',template:['explorer','challenger','expert'].indexOf(id),apps:APP_TEMPLATES.map(defaultBuilder)});
const freshGame=()=>({difficulty:'explorer',theme:'dark',profiles:Object.fromEntries(DIFFICULTIES.map(d=>[d.id,freshProfile(d.id)])),bonus:{debug:[],quiz:[]}});
function safeIndices(v,max){return Array.isArray(v)?[...new Set(v.filter(n=>Number.isInteger(n)&&n>=0&&n<max))]:[];}
function normalizeProfile(raw,id){const p=freshProfile(id);if(!raw||typeof raw!=='object')return p;for(const k of ['completed','robotSolved','testReports'])p[k]=safeIndices(raw[k],3);p.robotLevel=Number.isInteger(raw.robotLevel)?Math.max(0,Math.min(2,raw.robotLevel)):0;p.elapsed=Number.isFinite(raw.elapsed)?Math.max(0,Math.floor(raw.elapsed)):0;p.reflection=['dev','test','both'].includes(raw.reflection)?raw.reflection:'';p.template=[0,1,2].includes(raw.template)?raw.template:p.template;if(Array.isArray(raw.apps))raw.apps.forEach((a,i)=>{if(!a||!p.apps[i])return;const t=APP_TEMPLATES[i];p.apps[i]={name:typeof a.name==='string'?a.name.slice(0,24):t.name,color:Number.isInteger(a.color)&&a.color>=0&&a.color<COLORS.length?a.color:0,rule:t.choices.some(c=>c[0]===a.rule)?a.rule:t.default,tests:Array.isArray(a.tests)?[...new Set(a.tests.filter(x=>t.tests.some(v=>v[0]===x)))]:[]};});return p;}
let game=freshGame();
try{const saved=JSON.parse(localStorage.getItem(STORE));if(saved&&typeof saved==='object'){game.difficulty=DIFFICULTIES.some(d=>d.id===saved.difficulty)?saved.difficulty:'explorer';game.theme=saved.theme==='light'?'light':'dark';DIFFICULTIES.forEach(d=>game.profiles[d.id]=normalizeProfile(saved.profiles?.[d.id],d.id));game.bonus.debug=safeIndices(saved.bonus?.debug,3);game.bonus.quiz=Array.isArray(saved.bonus?.quiz)?saved.bonus.quiz.slice(0,6).map((v,i)=>v&&Number.isInteger(v.answer)&&v.answer>=0&&v.answer<3?{answer:v.answer,correct:v.answer===QUIZ[i].correct}:null):[];}else{const old=JSON.parse(localStorage.getItem('kodra-fel-v1'));if(old){game.profiles.explorer=normalizeProfile(old,'explorer');if(old.builder){const b=old.builder;game.profiles.explorer.apps[0]={name:typeof b.name==='string'?b.name.slice(0,24):'Hangulatjelző',color:[0,1,2].includes(b.color)?b.color:0,rule:['sad','happy'].includes(b.rule)?b.rule:'sad',tests:Array.isArray(b.moods)?b.moods.filter(m=>['sad','happy'].includes(m)):[]};}}}}catch{}
let state=game.profiles[game.difficulty],currentView='home',currentMission=0,queue=[],robotPosition=null,visited=[],robotRunning=false,runVersion=0,chipCollected=false,currentScenario=0,testHistory=[],reportSelection=null,bonusKind='debug',bonusIndex=0,bonusSelection=null,bonusRevealed=false,lastDialogFocus,toastTimer;
const difficulty=()=>DIFFICULTIES.find(d=>d.id===game.difficulty);
const robotLevel=()=>ROBOT_LEVELS[game.difficulty][state.robotLevel];
const scenario=()=>TEST_SCENARIOS[game.difficulty][currentScenario];
const template=()=>APP_TEMPLATES[state.template];
const builder=()=>state.apps[state.template];
function totalXP(){return DIFFICULTIES.reduce((s,d)=>{const p=game.profiles[d.id];return s+p.completed.length*d.xp+p.robotSolved.length*20+p.testReports.length*15;},0)+(game.bonus.debug.length===3?120:0)+(game.bonus.quiz.filter(Boolean).length===6?120:0);}
function save(){try{localStorage.setItem(STORE,JSON.stringify(game));}catch{}updateHome();}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function scrollTopPage(){window.scrollTo({top:0,behavior:'instant'});}
function stopRun(){runVersion++;robotRunning=false;}
function applyTheme(){document.body.dataset.theme=game.theme;$('.theme-toggle').innerHTML=icon(game.theme==='dark'?'sun':'moon');$('.theme-toggle').setAttribute('aria-label',`${game.theme==='dark'?'Világos':'Sötét'} megjelenés bekapcsolása`);$('meta[name="theme-color"]').content=game.theme==='dark'?'#101b18':'#f7f8f4';}
function renderDifficulty(){ $('#difficulty-grid').innerHTML=DIFFICULTIES.map(d=>`<button class="difficulty-card ${game.difficulty===d.id?'selected':''}" data-action="difficulty" data-difficulty="${d.id}" aria-pressed="${game.difficulty===d.id}"><span class="difficulty-icon">${icon(d.icon)}</span><span class="difficulty-body"><span class="difficulty-tag">${d.tag}</span><strong>${d.name}<small>LVL ${d.level}</small></strong><span>${d.desc}</span></span><span class="difficulty-check">${game.difficulty===d.id?'✓':d.level}</span><span class="difficulty-track">${game.profiles[d.id].completed.length} / 3 küldetés</span></button>`).join('');$('#game-difficulty').innerHTML=DIFFICULTIES.map(d=>`<option value="${d.id}" ${game.difficulty===d.id?'selected':''}>${d.name}</option>`).join('');}
function updateHome(){const count=state.completed.length,xp=totalXP();$('#home-progress').textContent=`${difficulty().name} · ${count} / 3 teljesítve`;$('#home-ring').style.background=`conic-gradient(#9dcf66 ${count/3*360}deg, transparent 0)`;[0,1,2].forEach(i=>$('#tick-'+i).hidden=!state.completed.includes(i));$('#nav-count').textContent=count===3?'✓':'3';$('#start-button').innerHTML=(count===3?'Eredmények megtekintése':state.elapsed>0?'Folytatom a kalandot':'Induljon a kaland')+icon('arrow');$('#total-xp').textContent=`${xp} XP`;const rank=xp>=1200?'Digitális alkotó':xp>=600?'Tech kalandor':xp>=300?'Ügyes felfedező':'Kíváncsi újonc';$('#player-rank').textContent=rank;const next=xp<300?300:xp<600?600:xp<1200?1200:1905;$('#xp-caption').textContent=`${xp} / ${Math.max(next,xp)} XP`;$('#xp-fill').style.width=`${Math.min(100,xp/next*100)}%`;renderDifficulty();}
function setView(view){stopRun();currentView=view;['home','game','profession','learn','badges'].forEach(v=>$('#'+v+'-view').hidden=view!==v);$$('.main-nav .nav-item').forEach(b=>b.classList.remove('active'));const target=view==='profession'?'[data-action="professions"]':view==='game'?'#nav-missions':view==='learn'?'#nav-learn':view==='badges'?'#nav-badges':'#nav-home';$(target)?.classList.add('active');scrollTopPage();}
function focusTitle(){const h=$('h1',$('#'+currentView+'-view'));if(h){h.tabIndex=-1;h.focus({preventScroll:true});}}
function goHome(){setView('home');updateHome();focusTitle();}
function chooseDifficulty(id){if(!DIFFICULTIES.some(d=>d.id===id))return;const oldMission=currentMission,wasGame=currentView==='game';stopRun();game.difficulty=id;state=game.profiles[id];save();updateTimer();if(wasGame&&oldMission>=0&&oldMission<3)openMission(oldMission);else if(wasGame)goHome();toast(`${difficulty().name} szint kiválasztva. Minden szint haladása külön megmarad.`);}
function start(){if(state.completed.length===3)showResults();else openMission([0,1,2].find(i=>!state.completed.includes(i))??0);}
function renderSteps(){const bonus=currentMission>2;$('#game-steps').hidden=bonus;$('.game-difficulty-label').hidden=bonus;$('#game-steps').innerHTML=['Fejlesztő','Tesztelő','Alkotó'].map((t,i)=>`<button class="game-step ${currentMission===i?'active':''}" data-action="mission" data-mission="${i}" data-short="${t}" ${currentMission===i?'aria-current="step"':''}><span class="step-num">${state.completed.includes(i)?'✓':String(i+1).padStart(2,'0')}</span><span>${t}</span><span class="step-xp">+${difficulty().xp} XP</span></button>`).join('');}
function openMission(n){if(![0,1,2].includes(n))return;setView('game');currentMission=n;renderSteps();if(n===0){queue=[];robotPosition=null;visited=[];chipCollected=false;renderRobot();}if(n===1){currentScenario=[0,1,2].find(i=>!state.testReports.includes(i))??0;testHistory=[];reportSelection=null;renderTest();}if(n===2)renderBuilder();focusTitle();}
function gameTitle(label,title,description,progress){return `<div class="game-title-row"><div class="game-title"><div class="eyebrow">${label}</div><h1>${title}</h1><p>${description}</p></div>${progress?`<span class="sublevel-pill">${progress}</span>`:''}</div>`;}
const note=text=>`<div class="learning-note">${icon('light')}<span>${text}</span></div>`;
function boardMarkup(){const l=robotLevel(),pos=robotPosition||l.start;let html='';for(let y=0;y<l.size;y++)for(let x=0;x<l.size;x++){const wall=l.walls.some(w=>w[0]===x&&w[1]===y),goal=l.goal[0]===x&&l.goal[1]===y,chip=l.chip&&l.chip[0]===x&&l.chip[1]===y&&!chipCollected,bot=pos[0]===x&&pos[1]===y;html+=`<div class="board-cell ${wall?'wall ':''}${goal?'goal ':''}${chip?'chip ':''}${visited.some(p=>p[0]===x&&p[1]===y)?'visited ':''}" role="img" aria-label="${y+1}. sor, ${x+1}. oszlop: ${bot?'robot':goal?'cél':chip?'adatcsip':wall?'akadály':'szabad mező'}">${bot?'<span class="cell-bot" aria-hidden="true"><i></i><i></i></span>':goal?'✦':chip?'◆':''}</div>`;}return html;}
function renderRobot(){const l=robotLevel(),advanced=game.difficulty!=='explorer';$('#game-content').innerHTML=gameTitle('01 / FEJLESZTŐ · A TE UTASÍTÁSAID, BIT KALANDJA',l.title,l.intro,`${difficulty().name} · ${l.size} × ${l.size}`)+`<div class="level-tabs" aria-label="Robotpályák">${ROBOT_LEVELS[game.difficulty].map((p,i)=>`<button class="level-tab ${i===state.robotLevel?'active':''}" data-action="robot-level" data-level="${i}" ${i===state.robotLevel?'aria-current="step"':''}><span>${state.robotSolved.includes(i)?'✓':'0'+(i+1)}</span>${p.title}</button>`).join('')}</div><div class="game-layout robot-layout"><div class="game-panel board-panel"><div class="panel-heading"><h2>Bit játszótere</h2><span class="panel-tag"><span></span><span id="run-status">Készen áll</span></span></div><div class="robot-board-wrap"><div class="robot-board" id="robot-board" style="grid-template-columns:repeat(${l.size},1fr)" data-size="${l.size}">${boardMarkup()}</div><div class="board-legend"><span><i class="legend-box start"></i>Bit</span><span>✦ Cél</span>${l.chip?'<span>◆ Adatcsip</span>':''}<span><i class="legend-box wall"></i>Akadály</span></div></div><div class="board-metrics"><span>${icon('flag')}3 pálya ezen a szinten</span><span>${icon('bolt')}+20 XP / új pálya</span></div><p class="panel-description">A „Fel” mindig a képernyő teteje felé visz. ${l.chip?'A lila csipet fel kell venned a cél előtt.':'A robot a teljes utasítássort követi; a végén érjen a csillaghoz.'}</p></div><div class="game-panel"><div class="panel-heading"><h2>A te programod</h2><button class="text-button" data-action="robot-hint">${icon('light')}Segítség</button></div><p class="panel-description">Válassz irányt! A hozzáadott blokkot kattintással törölheted. ${advanced?'Az ismétlés több azonos lépést fog össze.':'Egy nyíl egy mezőt jelent.'}</p><div class="repeat-row"><label for="repeat-count">Utasítás ismétlése</label><select id="repeat-count" aria-label="Új utasítás ismétlésszáma"><option value="1">×1 — egyszer</option><option value="2">×2 — kétszer</option><option value="3">×3 — háromszor</option><option value="4">×4 — négyszer</option></select></div><div class="command-palette">${Object.entries(DIRECTIONS).map(([k,d])=>`<button class="command-button" data-action="add-command" data-direction="${k}" aria-label="${d.label} utasítás hozzáadása">${icon(d.icon)}${d.label}</button>`).join('')}</div><div class="queue-label">Utasítások sorrendben <span id="queue-count"></span></div><div class="command-queue" id="command-queue" aria-label="A robot programja"></div><div class="game-actions"><button class="button dark" data-action="run-robot" id="run-robot">${icon('play')}Program indítása</button><button class="button secondary" data-action="undo-command" id="undo-command">${icon('left')}Visszavonás</button><button class="icon-button" data-action="clear-commands" id="clear-commands" aria-label="Program törlése">${icon('reset')}</button></div><div id="robot-feedback" role="status" aria-live="polite"></div>${state.robotSolved.length===3?'<button class="button primary saved-continue" data-action="finish-robot">Mindhárom pálya kész! Jelvény átvétele'+icon('arrow')+'</button>':''}</div></div>`+note(`<strong>Ezt tanulod közben:</strong> ${l.note}`);renderQueue();}
function renderQueue(active=-1){const steps=queue.reduce((s,c)=>s+c.repeat,0);$('#command-queue').innerHTML=queue.length?queue.map((c,i)=>`<button class="queue-item ${active===i?'running':''}" data-action="remove-command" data-index="${i}" aria-label="${i+1}. blokk: ${DIRECTIONS[c.dir].label}, ${c.repeat} alkalommal. Törlés." ${robotRunning?'disabled':''}><span>${i+1}.</span>${icon(DIRECTIONS[c.dir].icon)}${c.repeat>1?`<b>×${c.repeat}</b>`:''}</button>`).join(''):'<span class="queue-empty">A programod itt áll össze. Válaszd az első irányt!</span>';$('#queue-count').textContent=`${queue.length} blokk · ${steps} lépés`;$('#run-robot').disabled=robotRunning||!steps;$('#clear-commands').disabled=robotRunning||!steps;$('#undo-command').disabled=robotRunning||!steps;$('#repeat-count').disabled=robotRunning;$$('.command-button').forEach(b=>b.disabled=robotRunning);}
function robotFeedback(type,title,text){$('#robot-feedback').innerHTML=`<div class="feedback ${type}"><strong>${title}</strong>${text}</div>`;}
async function runRobot(){if(robotRunning||!queue.length)return;robotRunning=true;const version=++runVersion,l=robotLevel();robotPosition=[...l.start];visited=[];chipCollected=false;$('#robot-feedback').innerHTML='';$('#robot-board').innerHTML=boardMarkup();const commands=queue.flatMap((c,i)=>Array.from({length:c.repeat},()=>({dir:c.dir,block:i})));let failed=false;for(let i=0;i<commands.length;i++){renderQueue(commands[i].block);$('#run-status').textContent=`Futás · ${i+1} / ${commands.length}`;await new Promise(r=>setTimeout(r,matchMedia('(prefers-reduced-motion: reduce)').matches?30:game.difficulty==='explorer'?300:150));if(version!==runVersion||currentView!=='game'||currentMission!==0)return;const d=DIRECTIONS[commands[i].dir],n=[robotPosition[0]+d.dx,robotPosition[1]+d.dy];if(n[0]<0||n[1]<0||n[0]>=l.size||n[1]>=l.size||l.walls.some(w=>w[0]===n[0]&&w[1]===n[1])){failed=true;robotFeedback('error',`A(z) ${i+1}. lépésnél elakadtam!`,`A(z) ${commands[i].block+1}. blokk akadályra vagy a pályán kívülre vinne. Kattints a blokkra a törléshez, majd próbáld újra. A robot mindig a startról indul.`);break;}visited.push([...robotPosition]);robotPosition=n;if(l.chip&&n[0]===l.chip[0]&&n[1]===l.chip[1])chipCollected=true;$('#robot-board').innerHTML=boardMarkup();}robotRunning=false;renderQueue();$('#run-status').textContent=failed?'Javításra vár':'Futás kész';if(failed)return;const reached=robotPosition[0]===l.goal[0]&&robotPosition[1]===l.goal[1];if(!reached){robotFeedback('error','Már mozog a programod!','A program véget ért, de Bit még nincs a csillagnál. Egészítsd ki az utasításokat, vagy tervezz másik utat.');return;}if(l.chip&&!chipCollected){robotFeedback('error','A cél megvan, de a csip még hiányzik.','A program feladata két részből áll: először adatcsip, utána célba érés. Tervezd bele az útvonalba a lila ◆ mezőt is!');return;}const first=!state.robotSolved.includes(state.robotLevel);if(first)state.robotSolved.push(state.robotLevel);save();const next=[0,1,2].find(i=>!state.robotSolved.includes(i));robotFeedback('success',`Bit célba ért! ${first?'+20 XP':'Újra sikerült!'}`,`<span>${commands.length} lépés, ${queue.length} utasításblokk. ${l.note}</span><br><button class="button primary" style="margin-top:12px" data-action="${next===undefined?'finish-robot':'robot-level'}" ${next!==undefined?`data-level="${next}"`:''}>${next===undefined?'Fejlesztői jelvény átvétele':'Jöhet a következő pálya'}${icon('arrow')}</button>`);celebrate(15);}
function robotHint(){const l=robotLevel();let route=l.chip?[...findRoute(l,l.start,l.chip),...findRoute(l,l.chip,l.goal)]:findRoute(l);const arrows={up:'↑',right:'→',down:'↓',left:'←'};const groups=[];route.forEach(k=>{const last=groups.at(-1);if(last?.k===k)last.n++;else groups.push({k,n:1});});robotFeedback('', 'Bit útvonaltippje',`Egy lehetséges útvonal a starttól: <span class="hint-route">${groups.map(g=>`${arrows[g.k]}${g.n>1?' ×'+g.n:''}`).join(' · ')}</span>Az ismétlésszámot a nyíl hozzáadása előtt állíthatod. Ha 4-nél több lépést látsz egy irányba, több blokkra oszd.`);}
function probeLabel(v){return v===''?'üres mező':v.trim()===''?`${v.length} szóköz`:v;}
function testOutput(s,value){const n=Number(value),v=value.trim();switch(s.kind){case 'coupon':return v.normalize('NFC').toLocaleUpperCase('hu-HU')==='DIÁK'?'Kupon elfogadva! Fizetendő: 2 000 Ft':'Nincs kedvezmény. Fizetendő: 2 000 Ft';case 'name':return 'Sikeres jelentkezés! ✓';case 'age':return v&&n>14?'Jelentkezés elfogadva ✓':'Legalább 14 évesnek kell lenned.';case 'quantity':return !v||!Number.isInteger(n)||n===0||n>5?'Érvénytelen darabszám.':`Fizetendő: ${(n*1000).toLocaleString('hu-HU')} Ft`;case 'search':return v==='Robot'?'Találat: Robotépítő műhely':'Nincs találat.';case 'length':return v.length>0&&v.length<8?'Név elfogadva ✓':'A név túl rövid vagy túl hosszú.';case 'shipping':return !v||n<0?'Érvénytelen kosárérték.':n>10000?'Szállítás: 0 Ft':'Szállítás: 990 Ft';case 'range':return !v||!Number.isInteger(n)||n<0||n>120?'Érvénytelen életkor.':n>=14||n<=18?'Belépés engedélyezve ✓':'A klub 14–18 éveseknek szól.';case 'healthy':return v?'Név elfogadva ✓':'Adj meg egy nevet!';}}
function renderTest(){const s=scenario(),done=state.testReports.includes(currentScenario);$('#game-content').innerHTML=gameTitle('02 / TESZTELŐ · ITT A JÓ KÉRDÉS A SZUPERERŐD','Kapd el a hibát!','Olvasd el a szabályt, próbáld ki a megadott eseteket, és jelentsd, amit tényleg megfigyeltél. A demóban szándékosan elhelyezett hibák vannak; profi szinten egy helyes működést is vizsgálsz.',`${difficulty().name} · ${state.testReports.length} / 3 kész`)+`<div class="scenario-tabs">${TEST_SCENARIOS[game.difficulty].map((a,i)=>`<button class="scenario-tab ${i===currentScenario?'active':''}" data-action="scenario" data-scenario="${i}" ${i===currentScenario?'aria-current="step"':''}>${state.testReports.includes(i)?'✓ ':String(i+1)+'. '}${a.title}</button>`).join('')}</div><div class="game-layout"><div class="game-panel"><div class="panel-heading"><h2>TesztLab / ${s.title}</h2><span class="panel-tag">Gyakorlóalkalmazás</span></div><div class="test-app"><div class="test-app-bar"><span aria-hidden="true">● ● ●</span><span>tesztlab.demo</span>${icon('lock')}</div><div class="test-app-body"><div class="demo-brand">${icon('bolt')}TesztLab</div><h3>${s.title}</h3><p>Kitalált app · valódi gondolkodás</p><form id="test-form" novalidate><label class="app-field">${s.label}<input id="test-input" type="${s.inputType}" value="${escapeHTML(s.value||'')}" placeholder="${escapeHTML(s.placeholder||'Írj be egy tesztértéket')}" autocomplete="off" ${s.inputType==='text'?'maxlength="50"':''}></label><button type="submit" class="demo-submit">Eset kipróbálása${icon('play')}</button><div class="demo-output" id="test-output" role="status" aria-live="polite">Várom a próbádat…</div></form></div></div><div class="test-history"><h3>Próbanapló <span id="test-history-count">0 próba</span></h3><div id="test-history"><p>Minden kipróbált érték itt jelenik meg.</p></div></div></div><div class="game-panel"><div class="panel-heading"><h2>A tesztelő jegyzetei</h2>${icon('bug')}</div><div class="spec-box"><strong>ÍGY KELLENE MŰKÖDNIE</strong>${s.task}</div><p class="panel-description">Ezeket az eseteket ellenőrizd! A gombok kitöltik a mezőt, de a próbát neked kell elindítanod.</p><div class="probe-chips">${s.probes.map((v,i)=>`<button data-action="probe" data-probe="${i}">${escapeHTML(probeLabel(v))}</button>`).join('')}</div><h3 class="report-step-title">Mi a pontos megállapításod?</h3><div class="report-options">${s.options.map((o,i)=>`<button class="report-option" data-action="report-option" data-option="${i}" aria-pressed="false">${o}</button>`).join('')}</div><p class="test-count" id="test-count">${done?'✓ Ezt a helyzetet már megoldottad. Újra ellenőrizheted.':'Először próbáld ki az összes megadott esetet!'}</p><div class="game-actions"><button class="button dark" id="report-submit" data-action="submit-report" disabled>Jelentés beküldése${icon('arrow')}</button></div><div id="test-feedback" role="status" aria-live="polite"></div>${state.testReports.length===3?'<button class="button primary saved-continue" data-action="finish-test">Mindhárom kész! Jelvény átvétele'+icon('arrow')+'</button>':''}</div></div>`+note('<strong>Tesztelői gondolkodás:</strong> szabály → bemenet → megfigyelt eredmény → pontos jelentés. Egy jó jelentésből más is meg tudja ismételni a helyzetet.');$('#test-form').addEventListener('submit',e=>{e.preventDefault();runTest();});}
function probesDone(){return scenario().probes.every(v=>testHistory.some(h=>h.input===v));}
function runTest(){const s=scenario(),v=$('#test-input').value,out=testOutput(s,v);testHistory.push({input:v,output:out});$('#test-output').textContent=out;$('#test-history-count').textContent=`${testHistory.length} próba`;$('#test-history').innerHTML=testHistory.slice(-7).map(h=>`<div class="history-entry"><code>${escapeHTML(probeLabel(h.input))}</code><span>${escapeHTML(h.output)}</span></div>`).join('');$$('.probe-chips button').forEach((b,i)=>b.classList.toggle('tried',testHistory.some(h=>h.input===s.probes[i])));const count=s.probes.filter(v=>testHistory.some(h=>h.input===v)).length;$('#test-count').textContent=probesDone()?'✓ Minden kért esetet kipróbáltál. Mit mutatnak az eredmények?':`${count} / ${s.probes.length} kért eset kipróbálva`;$('#report-submit').disabled=!probesDone()||reportSelection===null;}
function submitReport(){if(!probesDone()||reportSelection===null)return;const s=scenario();if(reportSelection!==s.correct){$('#test-feedback').innerHTML='<div class="feedback error"><strong>Nézzük meg még egyszer!</strong>A próbanaplót hasonlítsd a szabályhoz. Melyik mondat írja le pontosan a tapasztalt működést?</div>';return;}const first=!state.testReports.includes(currentScenario);if(first)state.testReports.push(currentScenario);save();const next=[0,1,2].find(i=>!state.testReports.includes(i));$('#test-feedback').innerHTML=`<div class="feedback success"><strong>Pontos megfigyelés! ${first?'+15 XP':'Újra megvan!'}</strong>${s.explanation}<br><button class="button primary" style="margin-top:12px" data-action="${next===undefined?'finish-test':'scenario'}" ${next!==undefined?`data-scenario="${next}"`:''}>${next===undefined?'Tesztelői jelvény átvétele':'Következő teszthelyzet'}${icon('arrow')}</button></div>`;$('#report-submit').disabled=true;celebrate(12);}
function renderBuilder(){const t=template(),b=builder();$('#game-content').innerHTML=gameTitle('03 / ALKOTÓ · ÖTLETBŐL MŰKÖDŐ MINIAPP','A te ötleted. A te appod.','Válassz egy projektet, formáld a saját stílusodra, és tedd helyessé a szabályát. A működő appodat a végén HTML-fájlként le is töltheted.','3 választható projekt')+`<div class="template-tabs" role="group" aria-label="Miniapp kiválasztása">${APP_TEMPLATES.map((a,i)=>`<button class="template-tab ${i===state.template?'active':''}" data-action="template" data-template="${i}" aria-pressed="${i===state.template}">${icon(a.icon)}<span><strong>${a.name}</strong><small>${a.desc}</small></span></button>`).join('')}</div><div class="game-layout"><div class="game-panel"><div class="panel-heading"><h2>Az ötleted műhelye</h2>${icon('spark')}</div><div class="builder-form"><div><label class="field-label" for="app-name">1. Mi legyen az app neve?</label><input class="app-name-input" id="app-name" maxlength="24" value="${escapeHTML(b.name)}" placeholder="Adj nevet az ötletednek!"></div><div><span class="field-label">2. Milyen színű legyen?</span><div class="swatches" role="group" aria-label="Az app színe">${COLORS.map((c,i)=>`<button class="swatch ${b.color===i?'active':''}" style="--swatch:${c}" data-action="app-color" data-color="${i}" aria-label="${['Zöld','Lila','Barack','Kék','Sárga'][i]}" aria-pressed="${b.color===i}"></button>`).join('')}</div></div><div><label class="field-label" for="app-rule">3. Tedd helyessé a szabályt!</label><p class="panel-description">${t.prompt}</p><div class="rule-builder"><span class="rule-keyword">HA</span> ${t.question.replace('HA ','')}<select id="app-rule">${t.choices.map(([v,label])=>`<option value="${v}" ${b.rule===v?'selected':''}>${label}</option>`).join('')}</select><br><span class="rule-keyword">AKKOR</span> ${t.then}<br><span class="rule-keyword">EGYÉBKÉNT</span> ${t.otherwise}</div></div></div><div class="release-checks" id="release-checks"></div><div class="game-actions" style="margin-top:20px"><button class="button dark" data-action="release-app">${icon('rocket')}Teszteltem, indulhat!</button></div><div id="builder-feedback" role="status" aria-live="polite"></div></div><div class="game-panel preview-panel"><div class="panel-heading"><h2>Élő előnézet</h2><span class="panel-tag"><span></span>Azonnal változik</span></div><div class="phone-preview" id="phone-preview" style="--app-color:${COLORS[b.color]}"><div class="phone-notch"></div><div class="phone-screen"><div class="phone-logo">${icon(t.icon)}</div><h3 id="phone-title">${escapeHTML(b.name)||'A te appod'}</h3><p>${t.id==='mood'?'Ma hogy érzed magad?':t.id==='ticket'?'Válassz életkort!':'Mennyi ideje fókuszálsz?'}</p><div class="mood-buttons">${t.tests.map(([v,label])=>`<button class="mood-button ${t.id!=='mood'?'numeric':''}" data-action="app-test" data-value="${v}" aria-label="${label} kipróbálása" aria-pressed="false">${t.id==='mood'?(v==='happy'?'😊':'😔'):label}</button>`).join('')}</div><div class="mood-output" id="mood-output" role="status" aria-live="polite">Kattints, és teszteld a szabályodat!</div></div></div><p class="preview-caption">Minden megadott esetet próbálj ki a kiadás előtt!</p><div class="miniapp-fact">${icon('code')}Egy feltételt állítasz be. A valódi programok is ilyen kis döntésekből épülnek.</div></div></div>`+note('<strong>Valódi munkafolyamat kicsiben:</strong> tervezés → elkészítés → tesztelés → javítás → kiadás. A szabály módosítása után újra kell tesztelned az appot.');$('#app-name').addEventListener('input',e=>{b.name=e.target.value;$('#phone-title').textContent=b.name||'A te appod';save();});$('#app-rule').addEventListener('change',e=>{b.rule=e.target.value;b.tests=[];$$('.mood-button').forEach(x=>{x.classList.remove('active');x.setAttribute('aria-pressed','false');});$('#mood-output').textContent='Új szabály! Próbáld ki újra az összes esetet.';$('#builder-feedback').innerHTML='';updateReleaseChecks();save();});updateReleaseChecks();}
function appResult(t,b,v){if(t.id==='mood')return v===b.rule?'Menni fog, lépésről lépésre! 💪':'Szuper, csak így tovább! ✨';if(t.id==='ticket'){const yes=b.rule==='lt'?Number(v)<14:b.rule==='lte'?Number(v)<=14:Number(v)>14;return yes?'1 000 Ft-os jegy':'2 000 Ft-os jegy';}const yes=b.rule==='gt'?Number(v)>25:b.rule==='gte'?Number(v)>=25:Number(v)<=25;return yes?'Jöhet egy rövid szünet! 🌿':'Még egy kis fókusz! 🎯';}
function updateReleaseChecks(){$('#release-checks').innerHTML=template().tests.map(([v,label])=>`<span class="${builder().tests.includes(v)?'passed':''}">${icon(builder().tests.includes(v)?'check':'clock')}${label} kipróbálása</span>`).join('');}
function testApp(v){const b=builder(),t=template();if(!t.tests.some(a=>a[0]===v))return;if(!b.tests.includes(v))b.tests.push(v);$$('.mood-button').forEach(x=>{x.classList.toggle('active',x.dataset.value===v);x.setAttribute('aria-pressed',String(x.dataset.value===v));});$('#mood-output').textContent=appResult(t,b,v);updateReleaseChecks();save();}
function releaseApp(){const b=builder(),t=template();const message=!b.name.trim()?'Adj nevet az appodnak!':b.tests.length<t.tests.length?'Előbb próbáld ki az összes gombot az előnézetben!':b.rule!==t.correct?`Még nem teljesül a feladat: ${t.prompt} Ellenőrizd a HA feltételt, javítsd, majd próbáld ki újra az összes esetet!`:'';if(message){$('#builder-feedback').innerHTML=`<div class="feedback error"><strong>Még egy apró lépés!</strong>${message}</div>`;return;}completeMission(2);}
function downloadApp(){const t=template(),b=builder();if(b.rule!==t.correct||b.tests.length<t.tests.length||!b.name.trim()){toast('Előbb készítsd el és teszteld az appot!');return;}const config=JSON.stringify({name:b.name,color:COLORS[b.color],id:t.id,rule:b.rule,tests:t.tests}).replace(/</g,'\\u003c');const html=`<!DOCTYPE html><html lang="hu"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHTML(b.name)}</title><style>*{box-sizing:border-box}body{font-family:system-ui;background:#f4f7ee;color:#263a2a;min-height:100dvh;margin:0;display:grid;place-items:center;padding:20px}main{background:white;padding:35px;border-radius:25px;max-width:420px;width:100%;box-shadow:0 15px 60px #203c2512}h1{overflow-wrap:anywhere}p{line-height:1.7;color:#62715a}nav{display:flex;gap:10px;margin:25px 0}button{border:1px solid #bccdaa;background:var(--accent);border-radius:12px;padding:15px;flex:1;cursor:pointer;font:inherit}output{display:block;min-height:70px;padding:20px;background:var(--accent);border-radius:12px;line-height:1.7}small{display:block;margin-top:25px;color:#62715a}button:focus-visible{outline:3px solid #315a28;outline-offset:4px}</style><main><h1>${escapeHTML(b.name)}</h1><p>${escapeHTML(t.prompt)}</p><nav aria-label="Próbaértékek"></nav><output aria-live="polite">Válassz egy lehetőséget!</output><small>Készült a Kódra fel! tech-kalandban.</small></main><script>const c=${config};document.documentElement.style.setProperty('--accent',c.color);c.tests.forEach(([v,label])=>{const b=document.createElement('button');b.textContent=label;b.onclick=()=>{let result;if(c.id==='mood')result=v===c.rule?'Menni fog, lépésről lépésre! 💪':'Szuper, csak így tovább! ✨';else if(c.id==='ticket')result=Number(v)<=14?'1 000 Ft-os jegy':'2 000 Ft-os jegy';else result=Number(v)>=25?'Jöhet egy rövid szünet! 🌿':'Még egy kis fókusz! 🎯';document.querySelector('output').textContent=result};document.querySelector('nav').append(b)});<\/script></html>`;downloadBlob(html,'sajat-miniapp.html','text/html;charset=utf-8');}
function downloadBlob(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function celebrate(n=25){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const box=document.createElement('div');box.className='confetti';box.setAttribute('aria-hidden','true');for(let i=0;i<n;i++){const p=document.createElement('i');p.style.cssText=`--x:${Math.random()*100}vw;--delay:${Math.random()*.4}s;--rot:${Math.random()*720}deg;background:${['#d5f793','#bdb0f2','#f4c6a7','#8ce4d4'][i%4]}`;box.append(p);}document.body.append(box);setTimeout(()=>box.remove(),2400);}
function completeMission(n){const first=!state.completed.includes(n);if(first)state.completed.push(n);save();renderSteps();if(state.completed.length===3){showResults();return;}const next=[0,1,2].find(i=>!state.completed.includes(i));$('#game-content').innerHTML=`<div class="completion-card"><div class="completion-icon">${icon(['code','bug','rocket'][n])}</div><div class="eyebrow">${difficulty().name.toLocaleUpperCase('hu-HU')} · ${state.completed.length} / 3 KÜLDETÉS</div><h1>${['Fejlesztői','Tesztelői','Alkotói'][n]} jelvény megszerezve!</h1><p>${['Lépésekre bontottál egy feladatot, megírtad az utasításokat, és kipróbáltad a megoldásodat. Ezt hívjuk fejlesztői gondolkodásnak.','Szabályokat ellenőriztél, teszteket futtattál és pontos megállapításokat tettél. A részletekre figyelő szemeddel jobbá tetted volna az appot.','Saját stílust és működési szabályt adtál egy miniappnak, majd teszteléssel ellenőrizted a megoldást. Az appod most letölthető!'][n]}</p><span class="earned-xp">${first?'+':''}${difficulty().xp} XP ${first?'megszerezve':'már megszerezve'}</span><div class="completion-actions"><button class="button primary" data-action="mission" data-mission="${next}">Következő küldetés${icon('arrow')}</button>${n===2?'<button class="button outline" data-action="download-app">'+icon('down')+'Saját app letöltése</button>':''}</div></div><div class="result-actions"><button class="text-button" data-action="home">Vissza a felfedezéshez${icon('arrow')}</button><button class="text-button" data-action="badges">Jelvényeim${icon('cup')}</button></div>`;celebrate();scrollTopPage();focusTitle();}
function showResults(){setView('game');currentMission=-1;renderSteps();$('#game-content').innerHTML=`<div class="completion-card"><div class="completion-icon">${icon('cup')}</div><div class="eyebrow">${difficulty().name.toLocaleUpperCase('hu-HU')} SZINT TELJESÍTVE</div><h1>A jövő alkotója? Akár te.</h1><p>Programoztál egy robotot, alkalmazást teszteltél és saját miniappot építettél. Nem kellett előre tudnod — elkezdted, és lépésről lépésre megtanultad.</p><div class="earned-badges"><span class="earned-badge">${icon('code')}Logikus gondolkodó</span><span class="earned-badge">${icon('bug')}Hibavadász</span><span class="earned-badge">${icon('rocket')}Ötletgazda</span></div><div class="completion-actions"><button class="button primary" data-action="professions">Milyen lehet ezt tanulni?${icon('arrow')}</button><button class="button outline" data-action="download-app">${icon('down')}Saját app letöltése</button></div></div><div class="reflection"><h2>Melyik pillanat volt a kedvenced?</h2><p>Ez egy élmény, nem alkalmassági teszt. Az XP a felfedezést jelzi, nem osztályzat.</p><div class="reflection-options">${[['dev','Amikor Bit célba ért'],['test','Amikor megtaláltam az eltérést'],['both','Amikor működött a saját appom']].map(([v,t])=>`<button data-action="reflection" data-value="${v}" class="${state.reflection===v?'selected':''}" aria-pressed="${state.reflection===v}">${t}</button>`).join('')}</div><div id="reflection-feedback" role="status">${state.reflection?note('Kérdezd meg a nyílt napon: „Milyen saját projekteket készíthetek nálatok?”'):''}</div></div><div class="next-adventure"><h2>Még tart a kíváncsiság?</h2><div class="game-actions">${DIFFICULTIES.filter(d=>d.id!==game.difficulty).map(d=>`<button class="button secondary" data-action="next-difficulty" data-difficulty="${d.id}">${icon(d.icon)}${d.name} szint</button>`).join('')}<button class="button secondary" data-action="bonus" data-bonus="debug">Kódnyomozó${icon('arrow')}</button></div></div><div class="result-actions"><button class="text-button" data-action="home">Vissza a felfedezéshez${icon('arrow')}</button><button class="text-button" data-action="reset">Új felfedező${icon('reset')}</button></div>`;celebrate(35);focusTitle();}
function openBonus(kind){if(!['debug','quiz'].includes(kind))return;setView('game');currentMission=kind==='debug'?3:4;bonusKind=kind;const data=kind==='debug'?DEBUG_PUZZLES:QUIZ;bonusIndex=kind==='debug'?data.findIndex((_,i)=>!game.bonus.debug.includes(i)):data.findIndex((_,i)=>!game.bonus.quiz[i]);if(bonusIndex<0)bonusIndex=0;bonusSelection=null;bonusRevealed=false;renderSteps();renderBonus();focusTitle();}
function renderBonus(){const data=bonusKind==='debug'?DEBUG_PUZZLES:QUIZ,p=data[bonusIndex];$('#game-content').innerHTML=gameTitle(`BÓNUSZ / ${bonusKind==='debug'?'KÓDNYOMOZÓ':'TECH RADAR'} · +120 XP`,bonusKind==='debug'?'Kis hiba, nagy felismerés.':'Hangold be a tech radarod!',bonusKind==='debug'?'Nem kell ismerned a programnyelveket. Olvasd el a helyzetet, gondolkodj végig a lépéseken, és javíts a logikán!':'Hat rövid kérdés, hat új felismerés. A válaszokhoz magyarázatot kapsz, és nyugodtan újra is próbálhatod.',`${bonusIndex+1} / ${data.length}`)+`<div class="bonus-progress">${data.map((_,i)=>`<span class="${i===bonusIndex?'active':i<bonusIndex?'done':''}"></span>`).join('')}</div><div class="puzzle-panel"><span class="puzzle-category">${bonusKind==='debug'?p.title:'TECH KÉRDÉS / '+String(bonusIndex+1).padStart(2,'0')}</span><h2>${bonusKind==='debug'?p.description:p.q}</h2>${bonusKind==='debug'?`<div class="code-window"><div class="code-window-bar"><span aria-hidden="true">● ● ●</span> gondolatmenet.txt</div>${p.code.map((line,i)=>`<div class="code-line"><span>${i+1}</span><code>${escapeHTML(line)}</code></div>`).join('')}</div>`:''}<div class="puzzle-options">${p.options.map((o,i)=>`<button class="report-option" data-action="bonus-option" data-option="${i}" aria-pressed="false"><span class="option-letter">${String.fromCharCode(65+i)}</span>${escapeHTML(o)}</button>`).join('')}</div><div class="game-actions"><button class="button primary" id="bonus-check" data-action="bonus-check" disabled>Megnézem${icon('arrow')}</button></div><div id="bonus-feedback" role="status" aria-live="polite"></div></div>`;}
function checkBonus(){if(bonusSelection===null||bonusRevealed)return;const data=bonusKind==='debug'?DEBUG_PUZZLES:QUIZ,p=data[bonusIndex],correct=bonusSelection===p.correct;if(!correct&&bonusKind==='debug'){$('#bonus-feedback').innerHTML='<div class="feedback error"><strong>Próbáld végig fejben!</strong>Melyik megoldás teljesíti pontosan a leírt célt? Nyugodtan válassz másik lehetőséget.</div>';return;}bonusRevealed=true;if(bonusKind==='debug'){if(!game.bonus.debug.includes(bonusIndex))game.bonus.debug.push(bonusIndex);}else if(!game.bonus.quiz[bonusIndex])game.bonus.quiz[bonusIndex]={answer:bonusSelection,correct};save();$('#bonus-check').disabled=true;$('#bonus-feedback').innerHTML=`<div class="feedback ${correct?'success':''}"><strong>${correct?'Pontosan!':'Ebből is tanultál!'}</strong>${!correct?'A helyes válasz: '+escapeHTML(p.options[p.correct])+'. ':''}${p.why}<br><button class="button primary" style="margin-top:14px" data-action="bonus-next">${bonusIndex===data.length-1?'Jöhet az összegzés':'Következő feladvány'}${icon('arrow')}</button></div>`;}
function bonusNext(){const data=bonusKind==='debug'?DEBUG_PUZZLES:QUIZ;if(bonusIndex<data.length-1){bonusIndex++;bonusSelection=null;bonusRevealed=false;renderBonus();scrollTopPage();return;}const completed=bonusKind==='debug'?game.bonus.debug.length===3:game.bonus.quiz.filter(Boolean).length===6;$('#game-content').innerHTML=`<div class="completion-card"><div class="completion-icon">${icon(bonusKind==='debug'?'code':'spark')}</div><div class="eyebrow">BÓNUSZKALAND ${completed?'TELJESÍTVE':'ÖSSZEGZÉS'}</div><h1>${bonusKind==='debug'?'Kódnyomozó lettél!':'A tech radarod élesítve.'}</h1><p>${bonusKind==='debug'?'Sorrendet, feltételt és ismétlést vizsgáltál. Ez a három ötlet rengeteg programban visszaköszön.':`${game.bonus.quiz.filter(v=>v?.correct).length} / 6 kérdésre elsőre jól válaszoltál. A többi magyarázatából is tanulhattál — itt a megértés a cél.`}</p><span class="earned-xp">${completed?'120 XP megszerezve · egyszeri jutalom':''}</span><div class="completion-actions"><button class="button primary" data-action="learn">Fedezz fel még több fogalmat${icon('arrow')}</button><button class="button outline" data-action="home">Vissza a kalandokhoz</button></div></div>`;celebrate();scrollTopPage();focusTitle();}
function openDialog(content){if($('#info-dialog').open)$('#info-dialog').close();lastDialogFocus=document.activeElement;$('#dialog-content').innerHTML=content;$('#info-dialog').showModal();}
function closeDialog(){$('#info-dialog').close();if(lastDialogFocus?.isConnected)lastDialogFocus.focus({preventScroll:true});}
function help(){openDialog(`<span class="mission-icon">${icon('help')}</span><h2 id="dialog-title">Itt szabad próbálkozni.</h2><p>Ha először találkozol programozással, válaszd a Felfedező szintet. A robotnál kérhetsz útvonaltippet, a tesztelői feladatokban pedig a mintabemenetek gombjai segítenek.</p><dl><dt>Miért gyűjtök XP-t?</dt><dd>A felfedezést jelzi. Új robotpályáért 20, új teszthelyzetért 15, küldetésért szinttől függően 100–200 XP jár. Egy teljes bónuszjáték 120 XP-t ad. Ugyanazért a teljesítésért csak egyszer kapsz jutalmat.</dd><dt>Egyedül vagy párban?</dt><dd>Mindkettő működik. Párban az egyikőtök tervezzen, a másik ellenőrizzen; utána cseréljetek!</dd><dt>Hol marad meg a haladás?</dt><dd>Ezen a gépen, ebben a böngészőben. A szintek haladása külön tárolódik. Nincs diákfiók vagy adatküldés.</dd><dt>Új diák érkezett?</dt><dd>Az „Új felfedező” minden helyi játékhaladást töröl. A megjelenés beállítása megmarad.</dd></dl><div class="game-actions"><button class="button primary" data-action="close-dialog">Mehet tovább!${icon('check')}</button><button class="text-button" data-action="reset">Új felfedező${icon('reset')}</button></div>${document.documentElement.hasAttribute('data-offline')?'':'<a class="text-button" style="margin-top:16px" href="kodra-fel-offline.zip" download>Offline változat letöltése'+icon('down')+'</a>'}`);}
function how(){openDialog(`<span class="mission-icon">${icon('flag')}</span><h2 id="dialog-title">Egy rövid kaland. Sok új ötlet.</h2><p>A Felfedező alapútvonal 5–10 percre készült. A magasabb szintek és a bónuszok hosszabb, szabad felfedezésre valók. Nincs időkorlát.</p><ol class="how-list"><li><span><strong>Válassz szintet!</strong>Felfedező: első lépések. Kihívó: labirintusok és összehasonlító tesztek. Profi: adatcsipek és több határérték.</span></li><li><span><strong>Próbáld ki mindhárom szerepet!</strong>Robotprogramozás → alkalmazástesztelés → saját miniapp. A feladatokat külön-külön is megnyithatod.</span></li><li><span><strong>Vidd tovább, ami érdekel!</strong>Két bónuszjáték, 15 fogalom és részletes szakmabemutató vár. A saját appodat le is töltheted.</span></li></ol><div class="game-actions"><button class="button primary" data-action="start-from-dialog">Induljon a kaland${icon('arrow')}</button></div>`);}
function resetDialog(){openDialog(`<span class="mission-icon">${icon('reset')}</span><h2 id="dialog-title">Új felfedező érkezik?</h2><p>Ez törli az összes nehézségi szint haladását, a jelvényeket, az XP-t és a miniappok helyi beállításait. A letöltött fájlokat nem érinti.</p><div class="game-actions"><button class="button dark" data-action="confirm-reset">Igen, tiszta lappal kezdek</button><button class="button secondary" data-action="close-dialog">Folytatom a kalandom</button></div>`);}
function updateTimer(){const seconds=state.elapsed;$('#timer').textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
const actions={
 home:goHome,missions:()=>{goHome();$('#missions').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});},start,mission:b=>openMission(Number(b.dataset.mission)),difficulty:b=>chooseDifficulty(b.dataset.difficulty),'next-difficulty':b=>{chooseDifficulty(b.dataset.difficulty);start();},theme:()=>{game.theme=game.theme==='dark'?'light':'dark';applyTheme();save();},professions:()=>{setView('profession');renderProfessionExtras();focusTitle();},learn:()=>{setView('learn');renderLearn();focusTitle();},badges:()=>{setView('badges');renderBadges();focusTitle();},help,how,'close-dialog':closeDialog,'start-from-dialog':()=>{closeDialog();start();},'bit-message':()=>{const messages=['Szia! Én Bit vagyok. Te tervezel, én pontosan követem az utasításaidat.','A hibázás adat. Próbáld ki, figyeld meg, és javíts egy lépést!','Kezdd a Felfedező szinten. Az első programodhoz három nyíl is elég.','Az ismétlés nem csalás: a → ×3 egy teljesen rendes program!'];toast(messages[Math.floor(Math.random()*messages.length)]);},
 'add-command':b=>{if(robotRunning)return;const repeat=Number($('#repeat-count').value),limit=game.difficulty==='explorer'?24:120;if(queue.reduce((s,c)=>s+c.repeat,0)+repeat>limit){toast(`Ebbe a programba legfeljebb ${limit} lépés fér. Használd a törlést vagy a visszavonást!`);return;}queue.push({dir:b.dataset.direction,repeat});renderQueue();},'remove-command':b=>{if(!robotRunning){queue.splice(Number(b.dataset.index),1);renderQueue();}},'undo-command':()=>{if(!robotRunning){queue.pop();renderQueue();}},'clear-commands':()=>{if(!robotRunning){queue=[];robotPosition=null;visited=[];chipCollected=false;renderQueue();$('#robot-board').innerHTML=boardMarkup();$('#robot-feedback').innerHTML='';$('#run-status').textContent='Készen áll';}},'run-robot':runRobot,'robot-hint':robotHint,'robot-level':b=>{stopRun();state.robotLevel=Number(b.dataset.level);queue=[];robotPosition=null;visited=[];chipCollected=false;save();renderRobot();},'finish-robot':()=>{if(state.robotSolved.length===3)completeMission(0);},
 scenario:b=>{currentScenario=Number(b.dataset.scenario);testHistory=[];reportSelection=null;renderTest();},probe:b=>{$('#test-input').value=scenario().probes[Number(b.dataset.probe)];$('#test-input').focus();},'report-option':b=>{reportSelection=Number(b.dataset.option);$$('.report-option').forEach((o,i)=>{o.classList.toggle('selected',i===reportSelection);o.setAttribute('aria-pressed',String(i===reportSelection));});$('#report-submit').disabled=!probesDone();},'submit-report':submitReport,'finish-test':()=>{if(state.testReports.length===3)completeMission(1);},template:b=>{state.template=Number(b.dataset.template);save();renderBuilder();},'app-color':b=>{builder().color=Number(b.dataset.color);$('#phone-preview').style.setProperty('--app-color',COLORS[builder().color]);$$('.swatch').forEach((s,i)=>{s.classList.toggle('active',builder().color===i);s.setAttribute('aria-pressed',String(builder().color===i));});save();},'app-test':b=>testApp(b.dataset.value),'release-app':releaseApp,'download-app':downloadApp,
 reflection:b=>{state.reflection=b.dataset.value;$$('.reflection-options button').forEach(x=>{x.classList.toggle('selected',x.dataset.value===state.reflection);x.setAttribute('aria-pressed',String(x.dataset.value===state.reflection));});$('#reflection-feedback').innerHTML=note('Kérdezd meg a nyílt napon: „Milyen saját projekteket készíthetek nálatok?”');save();},bonus:b=>openBonus(b.dataset.bonus),'bonus-option':b=>{if(bonusRevealed)return;bonusSelection=Number(b.dataset.option);$$('.puzzle-options button').forEach((o,i)=>{o.classList.toggle('selected',i===bonusSelection);o.setAttribute('aria-pressed',String(i===bonusSelection));});$('#bonus-check').disabled=false;},'bonus-check':checkBonus,'bonus-next':bonusNext,reset:resetDialog,'confirm-reset':()=>{const theme=game.theme;game=freshGame();game.theme=theme;state=game.profiles.explorer;save();closeDialog();goHome();updateTimer();toast('Új felfedező, új kaland. Kódra fel!');}
};
 document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=actions[b.dataset.action];if(action){if(b.tagName==='A')e.preventDefault();action(b);}});
$('#game-difficulty').addEventListener('change',e=>chooseDifficulty(e.target.value));
$('#info-dialog').addEventListener('click',e=>{if(e.target!==$('#info-dialog'))return;const r=$('#info-dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();});
$('#info-dialog').addEventListener('cancel',e=>{e.preventDefault();closeDialog();});
document.addEventListener('visibilitychange',()=>{if(document.hidden)save();});
window.addEventListener('pagehide',save);
setInterval(()=>{if(currentView==='game'&&currentMission>=0&&!document.hidden&&!$('#info-dialog').open){state.elapsed++;updateTimer();if(state.elapsed%5===0)save();}},1000);
applyTheme();updateHome();updateTimer();
